import { EventEmitter } from 'eventemitter3';

export enum GameEvents {
    STATE_CHANGED = 'STATE_CHANGED',
    USER_CLICK_SPIN = 'USER_CLICK_SPIN',
    GRID_UPDATED = 'GRID_UPDATED',
    SPIN_RESPONSE_RECEIVED = 'SPIN_RESPONSE_RECEIVED',
    SPIN_PLAY_REQUESTED = 'SPIN_PLAY_REQUESTED',

    REEL_STOPPED = 'REEL_STOPPED',
    GAME_RESIZED = 'GAME_RESIZED',
    START_WIN_PRESENTATION = 'START_WIN_PRESENTATION',
}

export class EventDispather extends EventEmitter {
    private static instance: EventDispather;

    private constructor() {
        super();
    }

    public static getInstance(): EventDispather {
        if (!EventDispather.instance) {
            EventDispather.instance = new EventDispather();
        }
        return EventDispather.instance;
    }
}