import { AssetLoader } from "./AssetLoader";
import { AssetPreloading } from "./AssetPreloading";
export type AssetData = {
    alias: string;
    spritePath: string;
    jsonPath?: string;
};
export class AssetPreLoader extends AssetPreloading {

    loadDesktopAssets(): void {
    }
    loadMobileAssets(): void {
    }
    loadGameAssets(): void {
        AssetLoader.load("symbols-sheet", `${import.meta.env?.BASE_URL}/graphics/symbols.png`, `${import.meta.env?.BASE_URL}/graphics/symbols.json`, 'init');
        AssetLoader.load("game-backgrounds", `${import.meta.env?.BASE_URL}/graphics/background.jpg`, `${import.meta.env?.BASE_URL}/graphics/background.json`, 'init');
        AssetLoader.loadSpine('win-star', `${import.meta.env?.BASE_URL}/spine/star.json`, `${import.meta.env?.BASE_URL}/spine/star.atlas`, 'init');

    }
}